select 'scan_window', scan_id, status, round(extract(epoch from created_at)) created, round(extract(epoch from started_at)) started, round(extract(epoch from completed_at)) completed from tenant_xbow.scans where scan_id::text like '68a58881%' or scan_id::text like '1f5fe7c8%' or scan_id::text like '84aea81a%' or scan_id::text like '4ebd576b%' or scan_id::text like 'dbf83a85%' or scan_id::text like '947b04f7%' or scan_id::text like '6c4d84c3%' order by 4;
select 'ledger_state_now', scan_id, state, count(*) from tenant_xbow.ledger_cell where scan_id::text in ('68a58881-ae3b-4f36-90a9-bf254da13fcb','1f5fe7c8-5e28-45bc-8e08-a3e868bad87e','84aea81a-7e43-495c-9974-ca064ddd3552','4ebd576b-45b7-4cf3-a70c-0605f2adfc2a','dbf83a85-9ee8-4420-b344-a43c8d5ee2c5') group by 1,2 order by 1,3 desc;
